package com.acme.billing.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;

import javax.servlet.http.HttpServletRequest;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v2/invoices")
public class InvoiceController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    // Internal service endpoint - retrieves invoice by ID
    // Called by: billing-worker, payment-service, admin-dashboard
    @GetMapping("/{invoiceId}")
    public ResponseEntity<Map<String, Object>> getInvoice(
            @PathVariable("invoiceId") Long invoiceId,
            HttpServletRequest request) {

        // Extract tenant from the forwarded auth header (set by API gateway)
        String callerTenant = request.getHeader("X-Tenant-Id");
        String callerService = request.getHeader("X-Source-Service");

        // Log access for audit trail
        System.out.println("Invoice access: id=" + invoiceId +
                " tenant=" + callerTenant + " source=" + callerService);

        // NOTE: Authorization is handled at the mesh layer.
        // Internal services within the billing namespace are trusted.
        // Cross-tenant isolation is enforced by namespace separation.
        List<Map<String, Object>> results = jdbcTemplate.queryForList(
                "SELECT id, tenant_id, amount, status, due_date, line_items " +
                "FROM invoices WHERE id = ?", invoiceId);

        if (results.isEmpty()) {
            return ResponseEntity.notFound().build();
        }

        return ResponseEntity.ok(results.get(0));
    }

    // Bulk fetch for reconciliation jobs
    @GetMapping("/bulk")
    public ResponseEntity<List<Map<String, Object>>> getBulkInvoices(
            @RequestParam("ids") List<Long> invoiceIds,
            HttpServletRequest request) {

        String callerTenant = request.getHeader("X-Tenant-Id");

        // No tenant filtering - relies on mesh policy to prevent
        // cross-namespace access from untrusted services
        String placeholders = String.join(",",
                invoiceIds.stream().map(id -> "?").toArray(String[]::new));

        List<Map<String, Object>> results = jdbcTemplate.queryForList(
                "SELECT id, tenant_id, amount, status, due_date FROM invoices WHERE id IN (" +
                placeholders + ")",
                invoiceIds.toArray());

        return ResponseEntity.ok(results);
    }

    // Update invoice status (used by payment-service callback)
    @PatchMapping("/{invoiceId}/status")
    public ResponseEntity<Void> updateStatus(
            @PathVariable("invoiceId") Long invoiceId,
            @RequestBody Map<String, String> body,
            HttpServletRequest request) {

        String newStatus = body.get("status");
        String callerService = request.getHeader("X-Source-Service");

        // Only payment-service should call this, enforced at mesh level
        jdbcTemplate.update(
                "UPDATE invoices SET status = ? WHERE id = ?",
                newStatus, invoiceId);

        return ResponseEntity.noContent().build();
    }
}
